            var sigU2 = (n1 * n2 / 12) * ((N + 1) - tieSum / (N * (N - 1)));
            if (!(sigU2 > 0)) return null;
            var sigU = Math.sqrt(sigU2);
            // Continuity-corrected z, magnitude.
            var diff = Math.abs(U1 - muU);
            var z = (diff > 0.5) ? (diff - 0.5) / sigU : 0;
            // Exact p when both samples are small (n < 50) and there are
            // NO ties — matches R's wilcox.test default; otherwise the
            // continuity-corrected normal approximation. tail selects the
            // alternative ("two" | "greater" | "less"; greater => large U1).
            var _tl = tail || "two";
