            var sigV2 = nd * (nd + 1) * (2 * nd + 1) / 24 - tieSum / 48;
            if (!(sigV2 > 0)) return null;
            var sigV = Math.sqrt(sigV2);
            var diffStat = Math.abs(Vplus - muV);
            var z = (diffStat > 0.5) ? (diffStat - 0.5) / sigV : 0;
            // Exact p when n is small (< 50) with no ties and no dropped
            // zero differences — matches R's wilcox.test default; else
            // the continuity-corrected normal approximation. tail selects
            // the alternative ("two" | "greater" | "less").
            var _tl = tail || "two";
            var exact = (nd < 50 && tieGroupSizes.length === 0 && !zeroDropped);
            var p2;
            if (exact) {
                p2 = this.signedRankExactP(Vplus, nd, _tl);
            } else if (_tl === "greater") {
                p2 = 1 - this._normCDF((Vplus - muV - 0.5) / sigV);
            } else if (_tl === "less") {
                p2 = this._normCDF((Vplus - muV + 0.5) / sigV);
            } else {
                p2 = 2 * (1 - this._normCDF(Math.abs(z)));
            }
            if (p2 < 0) p2 = 0; if (p2 > 1) p2 = 1;
            // Carry descriptives for the inspector readout.
            var md = this.mean(diffs);
            var sdd = this.sd(diffs, md);
