                        // the Add pill isn't crowded against the separator.
                        "padding:2px 8px;margin:0 6px 0 0;cursor:pointer;" +
                        "display:inline-flex;align-items:center;gap:5px;" +
                        "font:inherit;border-radius:3px;line-height:1;color:#1a5fb4;";
