        // Friendly label for the selection (shown at the left of the
        // toolbar).
        function _quickToolbarLabelFor(sel) {
            if (sel === "yAxis") return "Y axis";
            if (sel === "xAxis") return "X axis";
            if (sel === "errorBars" || sel.indexOf("errorBars:") === 0) return "Error bars";
            if (sel === "legend" || sel === "likertLegend") return "Legend";
            if (sel === "dataPoints") return "Data points";
            if (sel === "global") return "Chart";
            if (sel === "visibility") return "Visibility";
            if (sel === "export") return "Export";
            if (sel === "help") return "Help";
            if (sel === "stats") return "Statistics";
            if (sel === "grid") return "Grid";
            if (sel === "facetAccent") return "Accent line";
            if (sel === "drawShapes") return "Draw shapes";
            if (sel === "anatomy") return "Chart parts";
            if (sel === "graphChooser") return "Which graph?";
            if (sel === "graphLint") return "Check my graph";
            if (sel === "a11yHelp") return "Accessibility";
            if (sel === "glossary") return "Glossary";
            if (sel === "barOutliers") return "Outliers";
            if (sel.indexOf("bars:") === 0) return "Bar";
            if (sel.indexOf("text:") === 0) {
                return "Text";
            }
            if (sel.indexOf("annotation:") === 0) {
                var aid = sel.substring(11);
                var a = (typeof findAnnotation === "function") ? findAnnotation(aid) : null;
                if (!a) return "Annotation";
                return a.kind === "line" ? "Line" :
                       a.kind === "arrow" ? "Arrow" :
                       a.kind === "curve" ? "Curve" :
                       a.kind === "rect" ? "Rectangle" :
                       a.kind === "ellipse" ? "Ellipse" :
                       a.kind === "triangle" ? "Triangle" :
                       a.kind === "polygon" ? "Polygon" :
                       a.kind === "diamond" ? "Diamond" :
                       a.kind === "star" ? "Star" :
                       a.kind === "text" ? "Text" :
                       a.kind === "bracket" ? "Bracket" :
                       a.kind === "statBox" ? "Stats box" :
                       a.kind === "refLine" ? "Ref line" :
                       "Annotation";
            }
            return "Selection";
        }
