            if (sel === "errorBars" || sel.indexOf("errorBars:") === 0) return '<svg width="13" height="13" aria-hidden="true"><line x1="6.5" y1="1.5" x2="6.5" y2="11.5" stroke="currentColor" stroke-width="1.6"/><line x1="2.5" y1="1.5" x2="10.5" y2="1.5" stroke="currentColor" stroke-width="1.6"/><line x1="2.5" y1="11.5" x2="10.5" y2="11.5" stroke="currentColor" stroke-width="1.6"/></svg>';
            if (sel === "yAxis" || sel === "xAxis") return '<svg width="14" height="13" aria-hidden="true"><path d="M2 1 V11 H13" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>';
